const data={pergola:{title:'Pergola Sistemleri',lead:'Açık alanları dört mevsim yaşayan mimari mekânlara dönüştürün.',body:'Bioklimatik ve açılır-kapanır pergola çözümlerini, yapının mimarisine uyum sağlayacak ölçü ve detaylarla projelendiriyoruz.',start:0},tente:{title:'Tente Sistemleri',lead:'Işık ve gölgeyi günün ritmine göre kontrol edin.',body:'Mafsallı, kasetli ve özel ölçü tente sistemleriyle konut ve ticari alanlara konforlu gölgelendirme sağlıyoruz.',start:4},cadir:{title:'Çadır Sistemleri',lead:'Etkinlikten endüstriyel kullanıma, güvenilir ve güçlü çözümler.',body:'Farklı açıklık ve kullanım senaryolarına uygun çadır sistemlerini sağlam konstrüksiyon ve nitelikli membranlarla üretiyoruz.',start:8},branda:{title:'Branda Sistemleri',lead:'Koruma, dayanıklılık ve işlev tek yapıda.',body:'İhtiyaca göre sabit veya hareketli branda sistemlerini, zorlu dış koşullara uygun malzemelerle özel ölçü üretiyoruz.',start:12},semsiye:{title:'Şemsiye Sistemleri',lead:'Geniş açıklıklarda zarif ve esnek gölgelendirme.',body:'Bahçe, teras, otel ve restoranlar için rüzgâr dayanımı yüksek, mimariyle bütünleşen profesyonel şemsiye sistemleri sunuyoruz.',start:16},gazebo:{title:'Gazebo Sistemleri',lead:'Bahçenizde sakin, korunaklı ve karakterli bir alan.',body:'Modern ve klasik çizgilerde gazebo ve kamelyaları, alanın peyzajına uyumlu malzeme ve ölçülerle tasarlıyoruz.',start:20}};
