document.title=`${p.title} | KRC Branda`;document.getElementById('productTitle').innerHTML=p.title.replace(' Sistemleri','<br><em>Sistemleri</em>');document.getElementById('productLead').textContent=p.lead;document.getElementById('productBody').textContent=p.body;const pics=IMG.slice(p.start,p.start+4);document.getElementById('heroImage').src=url(pics[0]);document.getElementById('heroImage').alt=p.title;document.getElementById('productGallery').innerHTML=pics.map((id,i)=>`<button class="gallery-item reveal" data-index="${i}"><img src="${url(id)}" alt="${p.title} uygulaması ${i+1}"><span>${p.title} / Uygulama ${String(i+1).padStart(2,'0')}</span></button>`).join('');
